  function evidenceSummary(id){const segments=evidenceSegments(id),durationBy={};for(const segment of segments){const status=String(segment.status||'UNKNOWN_EVIDENCE'),duration=Math.max(0,Number(segment.to_ms)-Number(segment.from_ms)+1);durationBy[status]=(durationBy[status]||0)+duration;}const parts=[];if(durationBy.GAP)parts.push(`Lücke ${fmtDuration(durationBy.GAP)}`);if(durationBy.NOT_INSTRUMENTED)parts.push(`nicht instrumentiert ${fmtDuration(durationBy.NOT_INSTRUMENTED)}`);if(durationBy.PURGED_BY_RETENTION)parts.push(`Retention ${fmtDuration(durationBy.PURGED_BY_RETENTION)}`);if(durationBy.UNKNOWN_EVIDENCE)parts.push(`unklar ${fmtDuration(durationBy.UNKNOWN_EVIDENCE)}`);if(!parts.length&&durationBy.AVAILABLE)return {label:'vollständig',klass:'ok',details:'Evidence: AVAILABLE'};if(parts.length)return {label:parts.join(' · '),klass:'warn',details:`Evidence-Segmente: ${segments.length}`};return {label:'kein Evidenznachweis',klass:'neutral',details:'Keine Evidence-Segmente im sichtbaren Zeitraum'};}
